bpy.ops.object.transform_apply(location=True,rotation=True,scale=True)
mat=bpy.data.materials.new('Muted grassy soil');mat.use_nodes=True;mat.diffuse_color=(.16,.245,.15,1)
p=mat.node_tree.nodes.get('Principled BSDF');p.inputs['Base Color'].default_value=mat.diffuse_color;p.inputs['Roughness'].default_value=.95
ground.data.materials.append(mat);parts.append(ground)
# Deduplicate identical PBR colors while preserving flame and ground materials.
canonical={}
for o in parts:
 for i,m in enumerate(o.data.materials):
  p=m.node_tree.nodes.get('Principled BSDF') if m.use_nodes else None
  key=tuple(round(v,5) for v in (p.inputs['Base Color'].default_value if p else m.diffuse_color))
  if key not in canonical:canonical[key]=m
  o.data.materials[i]=canonical[key]
